{
  "id": "SPEC-SETUP-IMMUTABLE-VERSION-005",
  "purpose": "Ensure setup-callisto installs exactly the requested immutable Callisto release and never substitutes a local checkout, mutable branch, or unpinned Git source after resolution failure.",
  "scope": "Composite-action source/version semantics, platform asset selection, product-tag to crate-version mapping, checksum and attestation verification, immutable fallbacks, failure diagnostics, and action contract tests.",
  "non_goals": [
    "Supporting Windows or Intel macOS before version 1.0.",
    "Using a mutable branch as an installation fallback.",
    "Building a local checkout unless source=local is explicitly selected.",
    "Apple Developer ID or notarization verification.",
    "Changing setup-callisto-wasm beyond sharing canonical product-version and verification helpers where applicable."
  ],
  "api_surface": [
    {
      "name": "setup-callisto inputs",
      "signature": "source: auto|release|registry|local; version: latest|X.Y.Z|callisto@X.Y.Z",
      "description": "An explicit resolver in which non-local modes produce one immutable semantic version before any download or install, and local mode alone builds the checked-out source.",
      "error_conditions": [
        "source=local is combined with an exact release version.",
        "latest cannot be resolved to one immutable version.",
        "An exact asset or registry package is unavailable or fails verification.",
        "The current operating system or architecture is unsupported."
      ]
    }
  ],
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "criterion": "An explicit X.Y.Z or callisto@X.Y.Z request resolves to that one semantic version. In source=auto only a confirmed not-found release asset may fall back to the registry package with that identical version; authorization, rate-limit, 5xx, timeout, transport, malformed response, checksum, attestation, extraction, or version failures are terminal. source=release and source=registry never switch sources. If the selected immutable source cannot supply and verify the exact version, setup exits nonzero and never invokes unpinned cargo install --git.",
      "is_error_case": true
    },
    {
      "id": "AC-002",
      "criterion": "latest is resolved once to an immutable product version before installation and that resolved version is printed. Fallback between release assets and the registry retains that exact resolved version; it never asks each source independently for its latest version and never falls back to a branch.",
      "is_error_case": true
    },
    {
      "id": "AC-003",
      "criterion": "source=local is the only mode that builds the current checkout, requires a Callisto workspace, rejects an exact release-version input, and reports the checkout commit and built CLI version. Merely running inside the Callisto monorepo cannot override source=auto, release, or registry.",
      "is_error_case": true
    },
    {
      "id": "AC-004",
      "criterion": "Release-asset installation supports exactly aarch64-apple-darwin, x86_64-unknown-linux-musl, and aarch64-unknown-linux-musl. Unsupported operating systems and architectures fail with an actionable diagnostic rather than selecting a Linux or amd64 default.",
      "is_error_case": true
    },
    {
      "id": "AC-005",
      "criterion": "Before extraction or PATH modification, the commit-pinned setup helper independently anchors the allowed `orin-dx/callisto` repository and release-build workflow path, then consumes SPEC-RELEASE-PRODUCT-MODEL-001's versioned public `callisto-release-metadata.json` contract and requires its repository/workflow claims to match that allowlist. It verifies metadata and the selected payload against the exact product tag, source commit, SHA256SUMS, immutable workflow commit, and GitHub artifact attestations, then requires the installed binary to report the resolved version. Downloaded metadata can narrow or bind policy but can never authorize its own repository or workflow trust root.",
      "is_error_case": true
    },
    {
      "id": "AC-006",
      "criterion": "The resolver has table-driven action tests covering every source mode, both exact-version spellings, latest pinning, local-checkout precedence, each supported platform mapping, every unsupported-platform error, release-to-registry fallback with the same pinned version, and proof that no failure path executes an unpinned Git installation.",
      "is_error_case": true
    },
    {
      "id": "AC-007",
      "criterion": "One checked-in `.github` helper owns source resolution, ProductReleaseId-equivalent tag/version parsing, asset mapping, checksum verification, metadata verification, and attestation verification for setup-callisto and setup-callisto-wasm. The helper consumes the release contract and cannot derive release rosters or names from mutable checkout configuration; any artifact-type-specific divergence is explicit and tested.",
      "is_error_case": true
    }
  ],
  "linked_requirement": "REQ-DRAFT-RELEASE-RECOVERY",
  "linked_research": "RESEARCH-RELEASE-MODELS",
  "spec_file_path": "docs/specs/SPEC-SETUP-IMMUTABLE-VERSION-005.json",
  "reasoning": "The existing action conflates checkout detection, source choice, and fallback. Making the source mode explicit removes the silent exact-version-to-main transition while retaining a fast local mode for repository workflows."
}
{
  "id": "SPEC-RELEASE-BASELINE-READINESS-006",
  "purpose": "Restore a green, current dependency-policy baseline for the exact Callisto release candidate without suppressing fixable security or registry findings.",
  "scope": "The workspace dependency declarations and Cargo.lock entries that select rustls and chacha20 through callisto-moon's Moon, Warpgate, Extism, and HTTP development/test dependency graph; current cargo-deny audit evidence; and focused Moon/WASM regression verification.",
  "non_goals": [
    "Broad dependency modernization unrelated to the confirmed audit failures.",
    "Adding RUSTSEC-2026-0285, rustls, chacha20, or a yanked-version exception to deny.toml.",
    "Changing Callisto's release product model, provider convergence model, setup resolution, or workspace membership semantics.",
    "Claiming that a lockfile-only update is safe without exercising the affected Moon, Extism, HTTP, and WASM test boundaries available in this repository."
  ],
  "api_surface": [],
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "criterion": "The committed dependency graph selects rustls 0.23.45 or newer throughout the workspace and a current cargo-deny audit no longer reports RUSTSEC-2026-0285; the fix uses a compatible dependency or lock update and does not add an advisory ignore.",
      "is_error_case": true
    },
    {
      "id": "AC-002",
      "criterion": "The committed dependency graph no longer selects yanked chacha20 0.10.1 through rand, retry-policies, reqwest-retry, Warpgate, Moon test utilities, or any sibling path; the fix does not add a yanked-version allowance.",
      "is_error_case": true
    },
    {
      "id": "AC-003",
      "criterion": "The update is the smallest compatible dependency transaction that fixes both confirmed failures. Every changed direct dependency constraint is justified by resolver evidence; unrelated packages are not upgraded merely because newer versions exist, and Cargo.lock remains reproducible from the checked-in manifests.",
      "is_error_case": false
    },
    {
      "id": "AC-004",
      "criterion": "The affected callisto-moon unit/integration tests, the real Moon/Extism sandbox tests, and `just wasm-check` pass after the update, proving the resolved runtime and HTTP/TLS stack still supports Callisto's current WASM plugin boundary.",
      "is_error_case": false
    },
    {
      "id": "AC-005",
      "criterion": "`just audit` passes against the advisory database current at verification time, and the remaining `just ci` stages pass. The audit timestamp and any environmental limitation are recorded; a stale or inaccessible advisory database is not reported as a green audit.",
      "is_error_case": true
    }
  ],
  "linked_requirement": "REQ-DRAFT-RELEASE-RECOVERY",
  "spec_file_path": "docs/specs/SPEC-RELEASE-BASELINE-READINESS-006.json",
  "reasoning": "The existing project-native audit is already the correct enforcement boundary. This specification narrows remediation to the two confirmed current-baseline failures so release-architecture work is not conflated with dependency modernization and cannot bypass a red candidate gate."
}
{
  "goal": "Restore a reproducible dependency graph that passes the current audit and preserves the Moon/WASM runtime boundary.",
  "architecture": "Keep the existing cargo-deny and Moon task boundaries authoritative. Perform one minimal resolver transaction for the confirmed rustls vulnerability and yanked chacha20 path, inspect every collateral lockfile change, and verify the affected runtime plus the complete project-native gates without adding policy exceptions.",
  "tech_stack": [
    "Cargo",
    "Cargo.lock",
    "cargo-deny",
    "Moon",
    "Extism",
    "RustSec",
    "just"
  ],
  "tasks": [
    {
      "id": "BR-001",
      "title": "Resolve the two confirmed dependency-policy failures minimally",
      "files": {
        "modify": [
          "Cargo.lock",
          "Cargo.toml",
          "crates/callisto-moon/Cargo.toml"
        ],
        "test": [
          "Cargo.lock",
          "deny.toml"
        ]
      },
      "steps": [
        "Record `cargo tree -i rustls@0.23.43` and `cargo tree -i chacha20@0.10.1` before mutation to identify every direct and transitive constraint; do not edit deny.toml.",
        "Use the smallest compatible Cargo resolver update that selects rustls >=0.23.45 and a non-yanked chacha20; change a direct manifest constraint only when the resolver proves the lockfile alone cannot satisfy the criterion.",
        "Inspect the complete Cargo.lock delta and revert unrelated resolver movement by tightening the update command or direct constraint; document every package that must move with the two target paths.",
        "Run `cargo tree -i rustls` and `cargo tree -i chacha20`; expect all selected rustls versions to be >=0.23.45 and no chacha20 0.10.1 node.",
        "Run `just test`; expect all workspace tests, including callisto-moon tests, to pass."
      ],
      "commit_message": "fix(deps): restore release audit baseline",
      "covers_criteria": [
        "AC-001",
        "AC-002",
        "AC-003",
        "AC-004"
      ]
    },
    {
      "id": "BR-002",
      "title": "Verify the current audit and Moon/WASM boundary",
      "files": {
        "test": [
          "Cargo.lock",
          "crates/callisto-moon/tests/moon_wasm_sandbox.rs",
          "deny.toml"
        ]
      },
      "steps": [
        "Run the project-native focused Moon test task through `just test`; expect the Moon/Extism sandbox and all callisto-moon unit/integration tests to pass.",
        "Run `just wasm-check`; expect callisto-moon to compile for wasm32-wasip1 with the configured PDK feature.",
        "Run `rtk env MOON_FORCE=true just audit` with a current reachable advisory database, bypassing Moon's input cache because advisory state is external to its hash; expect zero vulnerability and yanked-version failures and record verification time plus advisory database fetch or revision evidence.",
        "Run `just ci`; expect formatting, lint, workspace tests, doc tests, and audit to pass, then retain the forced-audit result as the authoritative current-advisory evidence. If advisory-database access is sandbox-blocked, rerun only the forced audit with authorized database access and report the environmental split explicitly.",
        "Deliberate-fault check: evaluate the pre-update Cargo.lock with the same current audit database or otherwise retain the observed baseline output; expect it to fail on RUSTSEC-2026-0285 and yanked chacha20 0.10.1 while the corrected lock passes."
      ],
      "commit_message": "test(deps): verify Moon release readiness",
      "depends_on": [
        "BR-001"
      ],
      "covers_criteria": [
        "AC-001",
        "AC-002",
        "AC-003",
        "AC-004",
        "AC-005"
      ]
    }
  ],
  "batches": [
    {
      "batch_id": "BR-B1",
      "title": "Dependency baseline remediation and verification",
      "target_crate": "workspace and callisto-moon",
      "task_ids": [
        "BR-001",
        "BR-002"
      ]
    }
  ],
  "linked_spec": "SPEC-RELEASE-BASELINE-READINESS-006",
  "spec_file_path": "docs/specs/SPEC-RELEASE-BASELINE-READINESS-006.json",
  "plan_file_path": "docs/projects/SPEC-RELEASE-BASELINE-READINESS-006.json",
  "spec_hash": "sha256:03e216b16c818a04f0f50c49c1128045c7482a47133d3c3e6206749971949aa2",
  "linked_requirement": "REQ-DRAFT-RELEASE-RECOVERY"
}

